using System.ComponentModel.DataAnnotations;
namespace EmployeeMonitoringAPI.Models;
public sealed class EmergencyContact { [Key] public int EmergencyContactId { get; set; } public int UserId { get; set; } public User? User { get; set; } public string Name { get; set; } = ""; public string Relationship { get; set; } = ""; public string Phone { get; set; } = ""; public string Email { get; set; } = ""; public bool IsPrimary { get; set; } }
public sealed class PromotionHistory { [Key] public int PromotionHistoryId { get; set; } public int UserId { get; set; } public User? User { get; set; } public int Year { get; set; } public string Quarter { get; set; } = ""; public string Status { get; set; } = "PendingHRReview"; public string FromDesignation { get; set; } = ""; public string ToDesignation { get; set; } = ""; public string ApprovedDesignation { get; set; } = ""; public string ManagerRecommendation { get; set; } = ""; public int? RecommendedById { get; set; } public DateTime EffectiveDate { get; set; } public int ApprovedById { get; set; } public DateTime? DecisionDate { get; set; } public string Remarks { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class ProjectDiscussion { [Key] public int ProjectDiscussionId { get; set; } public int ProjectId { get; set; } public Project? Project { get; set; } public int AuthorId { get; set; } public User? Author { get; set; } public string Message { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class EmployeeMessage { [Key] public long EmployeeMessageId { get; set; } public int SenderId { get; set; } public int RecipientId { get; set; } public string Subject { get; set; } = ""; public string Message { get; set; } = ""; public DateTime SentAt { get; set; } = DateTime.UtcNow; public DateTime? ReadAt { get; set; } }
